<html lang="en">
<head>
<meta charset="UTF-8">
<title>2D Cube Horror Top-Down</title>
<style>
body { margin:0; background:black; font-family:Arial; overflow:hidden;}
canvas { display:block; margin:0 auto; background:#111;}
#ui { text-align:center; color:white; margin-top:10px;}
</style>
</head>
<body>
<canvas id="game" width="600" height="400"></canvas>
<div id="ui">
❤️ HP: <span id="hp">30</span> | ⭐ XP: <span id="xp">0</span> | 🏆 LVL: <span id="lvl">1</span>
</div>

<script>
// Canvas
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");

// Карта (0=жол,1=қабырға)
const mapCols = 20;
const mapRows = 15;
const tileSize = 30;
let map = [];
for(let y=0;y<mapRows;y++){
  map[y] = [];
  for(let x=0;x<mapCols;x++){
    if(y==0 || y==mapRows-1 || x==0 || x==mapCols-1 || Math.random()<0.2) map[y][x]=1;
    else map[y][x]=0;
  }
}

// Player
let player = { x:5, y:5, hp:30, xp:0, level:1 };

// Monster
let monster = { x:15, y:10, size:1, speed:0.05 };

// Controls
let keys = {};
document.addEventListener("keydown", e=>{ keys[e.key]=true; });
document.addEventListener("keyup", e=>{ keys[e.key]=false; });

// Movement
function movePlayer(){
  let nx=player.x;
  let ny=player.y;
  if(keys["w"]) ny-=0.1;
  if(keys["s"]) ny+=0.1;
  if(keys["a"]) nx-=0.1;
  if(keys["d"]) nx+=0.1;
  // Collision
  if(map[Math.floor(ny)][Math.floor(nx)]==0){ player.x=nx; player.y=ny; }
}

// Monster AI
function moveMonster(){
  let dx = player.x - monster.x;
  let dy = player.y - monster.y;
  monster.x += dx*monster.speed;
  monster.y += dy*monster.speed;
}

// Collision
function checkCollision(){
  let dist = Math.hypot(player.x-monster.x, player.y-monster.y);
  if(dist < 1){
    player.hp -=0.5;
    if(player.hp<=0){
      alert("💀 Сені ұстап алды!");
      location.reload();
    }
  }
}

// Draw
function draw(){
  ctx.clearRect(0,0,canvas.width,canvas.height);
  // Map
  for(let y=0;y<mapRows;y++){
    for(let x=0;x<mapCols;x++){
      if(map[y][x]==1){
        ctx.fillStyle="#333";
        ctx.fillRect(x*tileSize, y*tileSize, tileSize, tileSize);
      }
    }
  }
  // Player
  ctx.fillStyle="cyan";
  ctx.fillRect(player.x*tileSize, player.y*tileSize, tileSize, tileSize);

  // Monster (2x үлкен)
  ctx.fillStyle="red";
  ctx.fillRect(monster.x*tileSize, monster.y*tileSize, tileSize*2, tileSize*2);
}

// Level Up
function levelUp(){
  if(player.xp>=player.level*10){
    player.level++;
    player.xp=0;
    let choice = prompt("LEVEL UP!\n1-HP +10\n2-Қару +2");
    if(choice=="1") player.hp+=10;
  }
}

// Loop
function loop(){
  movePlayer();
  moveMonster();
  checkCollision();
  draw();
  levelUp();
  // UI
  document.getElementById("hp").textContent=Math.floor(player.hp);
  document.getElementById("xp").textContent=player.xp;
  document.getElementById("lvl").textContent=player.level;
  requestAnimationFrame(loop);
}

loop();
</script>
</body>
</html>
